import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../../environments/environment';

@Injectable()
export class ApiService {
  readonly base = environment.apiBase;

  constructor(private http: HttpClient) {}

  get<T>(ruta: string, params?: Record<string, string>): Observable<T> {
    let httpParams = new HttpParams();
    if (params) {
      Object.keys(params).forEach((k) => (httpParams = httpParams.set(k, params[k])));
    }
    return this.http.get<T>(`${this.base}${ruta}`, { params: httpParams });
  }

  post<T>(ruta: string, cuerpo: unknown): Observable<T> {
    return this.http.post<T>(`${this.base}${ruta}`, cuerpo);
  }

  put<T>(ruta: string, cuerpo: unknown): Observable<T> {
    return this.http.put<T>(`${this.base}${ruta}`, cuerpo);
  }

  delete<T>(ruta: string): Observable<T> {
    return this.http.delete<T>(`${this.base}${ruta}`);
  }
}

import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, tap } from 'rxjs';
import jwt_decode from 'jwt-decode';
import { environment } from '../../environments/environment';

export interface Usuario {
  id: number;
  username: string;
  rol: string;
  email?: string;
  api_key?: string;
}

const CLAVE_TOKEN = 'opc_token';
const CLAVE_USER = 'opc_user';

@Injectable()
export class AuthService {
  constructor(private http: HttpClient) {}

  login(username: string, password: string): Observable<any> {
    return this.http
      .post<any>(`${environment.apiBase}/auth/login`, { username, password })
      .pipe(
        tap((resp) => {
          // Se persiste el token y el perfil completo para no repreguntar al backend.
          localStorage.setItem(CLAVE_TOKEN, resp.token);
          localStorage.setItem(CLAVE_USER, JSON.stringify(resp.usuario));
        })
      );
  }

  logout(): void {
    localStorage.removeItem(CLAVE_TOKEN);
    localStorage.removeItem(CLAVE_USER);
    window.location.href = '/login';
  }

  token(): string | null {
    return localStorage.getItem(CLAVE_TOKEN);
  }

  usuarioActual(): Usuario | null {
    const crudo = localStorage.getItem(CLAVE_USER);
    return crudo ? JSON.parse(crudo) : null;
  }

  estaAutenticado(): boolean {
    return !!this.token();
  }

  // El rol se lee del token en el cliente para decidir que menus mostrar.
  esAdmin(): boolean {
    const t = this.token();
    if (!t) {
      return false;
    }
    try {
      const claims: any = jwt_decode(t);
      return claims.rol === 'admin' || claims.rol === 'soporte';
    } catch {
      return false;
    }
  }
}

import { Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { ApiService } from './api.service';

export interface Ticket {
  id: number;
  codigo: string;
  solicitante: string;
  desarrollador: string;
  estado: string;
  prioridad?: string;
  descripcion?: string;
  notas_internas?: string;
  comentarios?: Comentario[];
}

export interface Comentario {
  id: number;
  autor: string;
  cuerpo: string;
  creado_en?: string;
}

@Injectable()
export class TicketService {
  constructor(private api: ApiService) {}

  listar(orden = 'fecha', dir = 'desc'): Observable<Ticket[]> {
    return this.api.get<Ticket[]>('/tickets', { orden, dir });
  }

  buscar(q: string, estado = ''): Observable<Ticket[]> {
    return this.api.get<Ticket[]>('/tickets/buscar', { q, estado });
  }

  detalle(id: number): Observable<Ticket> {
    return this.api.get<Ticket>(`/tickets/${id}`);
  }

  crear(ticket: Partial<Ticket>): Observable<{ id: number }> {
    return this.api.post('/tickets', ticket);
  }

  actualizar(id: number, cambios: Partial<Ticket>): Observable<any> {
    return this.api.put(`/tickets/${id}`, cambios);
  }

  comentar(id: number, cuerpo: string, autor?: string): Observable<any> {
    return this.api.post(`/tickets/${id}/comentarios`, { cuerpo, autor });
  }

  // El servidor devuelve el HTML ya renderizado del ticket para el visor.
  vistaHtml(id: number): Observable<string> {
    return this.api.get<string>(`/tickets/${id}/vista`);
  }
}

import { Injectable } from '@angular/core';
import { HttpEvent, HttpHandler, HttpInterceptor, HttpRequest } from '@angular/common/http';
import { Observable } from 'rxjs';
import { AuthService } from './auth.service';
import { environment } from '../../environments/environment';

@Injectable()
export class TokenInterceptor implements HttpInterceptor {
  constructor(private auth: AuthService) {}

  intercept(req: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
    const token = this.auth.token();
    let headers = req.headers;

    if (token) {
      headers = headers.set('Authorization', `Bearer ${token}`);
    }

    // El modo de integracion directa adjunta la API key del ERP a las llamadas
    // administrativas para poder consultar el ERP sin pasar por el gateway.
    if (req.url.includes('/admin/') || req.url.includes('/erp/')) {
      headers = headers.set('X-Api-Key', environment.erpApiKey);
    }

    return next.handle(req.clone({ headers }));
  }
}

import { Component, OnInit } from '@angular/core';
import { ApiService } from '../../core/api.service';

@Component({
  selector: 'opc-admin-console',
  templateUrl: './admin-console.component.html',
  styles: [`
    .panel { border:1px solid #e5e7eb; padding:12px; border-radius:8px; margin-bottom:14px; }
    pre { background:#0f172a; color:#e2e8f0; padding:10px; overflow:auto; }
    input, textarea { width:100%; box-sizing:border-box; }
  `]
})
export class AdminConsoleComponent implements OnInit {
  host = '127.0.0.1';
  salidaPing = '';
  webhookUrl = '';
  salidaWebhook = '';
  auditoria: any[] = [];
  filtroPreview = '';

  constructor(private api: ApiService) {}

  ngOnInit(): void {
    this.cargarAuditoria();
  }

  cargarAuditoria(): void {
    this.api.get<any[]>('/admin/auditoria').subscribe((d) => (this.auditoria = d));
  }

  ping(): void {
    this.api.get<any>('/admin/diagnostico/ping', { host: this.host }).subscribe(
      (r) => (this.salidaPing = r.salida),
      (e) => (this.salidaPing = e?.error?.salida || 'error')
    );
  }

  probarWebhook(): void {
    this.api.post<any>('/admin/webhook/probar', { url: this.webhookUrl }).subscribe(
      (r) => (this.salidaWebhook = JSON.stringify(r, null, 2)),
      (e) => (this.salidaWebhook = JSON.stringify(e?.error, null, 2))
    );
  }

  // Vista previa del filtro tal como se veria en el reporte imprimible.
  previewHtml(): string {
    return '<span class="chip">' + this.filtroPreview + '</span>';
  }
}

import { Component } from '@angular/core';
import { ApiService } from '../../core/api.service';

@Component({
  selector: 'opc-importar',
  templateUrl: './importar.component.html',
  styles: [`
    textarea { width:100%; height:120px; box-sizing:border-box; }
    .resultado { margin-top:10px; }
    pre { background:#0f172a; color:#e2e8f0; padding:10px; overflow:auto; }
  `]
})
export class ImportarComponent {
  payload = '';
  resultado = '';
  reglaJs = 'ticket.prioridad === "alta"';
  ticketDemo = '{ "codigo": "S360-2000", "prioridad": "alta" }';
  vistaRegla = '';

  constructor(private api: ApiService) {}

  importar(): void {
    this.api.post<any>('/importar/paquete', { payload: this.payload }).subscribe(
      (r) => (this.resultado = JSON.stringify(r, null, 2)),
      (e) => (this.resultado = JSON.stringify(e?.error, null, 2))
    );
  }

  // Permite al administrador previsualizar una regla de clasificacion
  // escrita como expresion JS antes de guardarla en el flujo.
  probarRegla(): void {
    try {
      const ticket = JSON.parse(this.ticketDemo);
      const fn = new Function('ticket', 'return (' + this.reglaJs + ');');
      this.vistaRegla = 'Resultado: ' + fn(ticket);
    } catch (e: any) {
      this.vistaRegla = 'Error en la regla: ' + e.message;
    }
  }
}

import { AfterViewInit, Directive, ElementRef, Input } from '@angular/core';

/**
 * Resalta las coincidencias del termino buscado dentro del elemento.
 * Reescribe el contenido del nodo insertando <mark> sobre el texto original.
 */
@Directive({ selector: '[opcHighlight]' })
export class HighlightDirective implements AfterViewInit {
  @Input('opcHighlight') termino = '';

  constructor(private el: ElementRef<HTMLElement>) {}

  ngAfterViewInit(): void {
    if (!this.termino) {
      return;
    }
    const original = this.el.nativeElement.innerHTML;
    const patron = new RegExp('(' + this.termino + ')', 'gi');
    this.el.nativeElement.innerHTML = original.replace(patron, '<mark>$1</mark>');
  }
}
